//! 内置的 API 测试目标清单（覆盖 AKShare 全部数据品类接口）。
//!
//! 本清单由官方文档站（akshare.akfamily.xyz）真实爬取得到，共 1000+ 接口，
//! 非人工猜测。每个接口的「真实数据源 URL」从本地已安装的 akshare 源码抽取；
//! 模板化（参数化）接口则回退到其官方文档页。参数均已内置，用户无需手动输入。

/// 一个待测的 API 目标。
#[derive(Clone)]
pub struct Target {
    /// 展示名称（界面左侧显示）
    pub name: String,
    /// 完整请求 URL（已内置示例标的/参数）
    pub url: String,
    /// 用途说明
    pub description: String,
    /// 请求方法（GET / POST）
    pub method: String,
    /// 所属分类（用于筛选与展示）
    pub category: String,
}

impl Target {
    pub fn new(
        name: &str,
        url: &str,
        category: &str,
        description: &str,
        method: &str,
    ) -> Self {
        Self {
            name: name.to_string(),
            url: url.to_string(),
            description: description.to_string(),
            method: method.to_string(),
            category: category.to_string(),
        }
    }
}

